param(
    [string]$BaseDir = (Get-Location).Path,
    [string]$InputCsvFolder = "",
    [string]$RootPartNumber = "ASM-SVR-001",
    [double]$BuildQty = 100,
    [int]$MaxScanFiles = 500,
    [int]$ChildTimeoutSec = 180,
    [bool]$OpenHtml = $true,
    [bool]$KeepPowerShellOpen = $true
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function def_NewUtf8NoBomEncoding { return [System.Text.UTF8Encoding]::new($false) }
function def_WriteText {
    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Text)
    $dir = Split-Path -Parent $Path
    if ($dir -and -not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    [System.IO.File]::WriteAllText($Path, $Text, (def_NewUtf8NoBomEncoding))
}
function def_WriteBytesFromBase64 {
    param([Parameter(Mandatory=$true)][string]$Path,[Parameter(Mandatory=$true)][string]$Base64Text)
    $dir = Split-Path -Parent $Path
    if ($dir -and -not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $clean = ($Base64Text -replace "`r", "" -replace "`n", "" -replace "`", "")
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($clean))
}
function def_Banner {
    param([string]$Title)
    Write-Host ""
    Write-Host "================================================================================" -ForegroundColor DarkCyan
    Write-Host "def $Title" -ForegroundColor Cyan
    Write-Host "================================================================================" -ForegroundColor DarkCyan
}

try {
    def_Banner "VIS HyperBOM Matrix · SELF-CONTAINED BOOTSTRAP + ALL-IN-ONE RUNNER v2"
    $BaseDir = (Resolve-Path -LiteralPath $BaseDir).Path
    $seedDir = Join-Path $BaseDir "_vis_hyperbom_seed_v2"
    $packageZip = Join-Path $seedDir "VIS_HyperBOM_Matrix_Package.zip"
    $runnerPath = Join-Path $seedDir "Run_VIS_HyperBOM_All_In_One.ps1"

    Write-Host "[POLICY] append-only · run-local · no delete · no canonical mutation · no SAP/PLM/MS Project write-back" -ForegroundColor Yellow
    Write-Host "[SEED]   $seedDir" -ForegroundColor Cyan

    $zipB64 = @'
`
`
`
`
`
`
`
`
`
`

'@
    $runnerB64 = @'
`
`
`
`
`
`
dGlvbiB3YXMgZXhlY3V0ZWQuIiAtRm9yZWdyb3VuZENvbG9yIEN5YW4KICAgICAgICBSZWFkLUhvc3QgIlByZXNzIEVudGVyIHRvIHJldHVybiB0byBwcm9tcHQiCiAgICB9Cn0K
'@

    def_WriteBytesFromBase64 -Path $packageZip -Base64Text $zipB64
    def_WriteText -Path $runnerPath -Text ([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(($runnerB64 -replace "`r", "" -replace "`n", "" -replace "`", ""))))

    Write-Host "[OK] Embedded HyperBOM package restored: $packageZip" -ForegroundColor Green
    Write-Host "[OK] Embedded runner restored        : $runnerPath" -ForegroundColor Green
    Write-Host "[RUN] Starting all-in-one governance matrix..." -ForegroundColor Cyan

    $argsList = @(
        "-NoProfile",
        "-ExecutionPolicy", "Bypass",
        "-File", $runnerPath,
        "-BaseDir", $BaseDir,
        "-RootPartNumber", $RootPartNumber,
        "-BuildQty", ([string]$BuildQty),
        "-MaxScanFiles", ([string]$MaxScanFiles),
        "-ChildTimeoutSec", ([string]$ChildTimeoutSec),
        "-OpenHtml", ([string]$OpenHtml),
        "-KeepPowerShellOpen", "False"
    )
    if ($InputCsvFolder -and (Test-Path -LiteralPath $InputCsvFolder)) {
        $argsList += @("-InputCsvFolder", (Resolve-Path -LiteralPath $InputCsvFolder).Path)
    }

    $pwshCmd = Get-Command pwsh -ErrorAction SilentlyContinue
    $psExe = if ($pwshCmd) { $pwshCmd.Source } else { (Get-Command powershell -ErrorAction Stop).Source }
    & $psExe @argsList
    $exitCode = $LASTEXITCODE
    if ($null -eq $exitCode) { $exitCode = 0 }
    Write-Host "[DONE] Child runner exit code: $exitCode" -ForegroundColor $(if ($exitCode -eq 0) { "Green" } else { "Yellow" })
} catch {
    Write-Host "[FATAL] $($_.Exception.Message)" -ForegroundColor Red
    Write-Host $_.ScriptStackTrace -ForegroundColor DarkRed
} finally {
    if ($KeepPowerShellOpen) {
        Write-Host ""
        Write-Host "PowerShell remains open. No destructive action was executed." -ForegroundColor Yellow
        Read-Host "Press Enter to return to prompt"
    }
}
